const timed=new Set(['searchExactPrerequisiteClosure','searchExactItinerantAgenda','searchStandaloneForCoreCandidate','searchJoint','necessary','repairedPrerequisites','attempt','findCanonicalPerfectMatching','materializeMatchingCandidate','assessCoreArrivalTransportFeasibility']);
registerHooks({load(url,context,next){const result=next(url,context);if(!/\/(assistedPlanning|exactItinerantPlan|exactMainAndFeederCore|macroScheduling|exactRoundSynchronization|transportGrouping)\.ts$/.test(url))return result;
