import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {PreparedFutureCollectiveParticipantClosure} from '../../engine/planner-next/futureCollectiveParticipantClosure';
import {canPlaceTask} from '../../engine/planner-next/placement';
const {searchExactPrerequisiteClosure}=await import('../../engine/planner-next/exactItinerantPlan') as any;
const recorded=JSON.parse(readFileSync('work/asst-s2/first-partial-hall.json','utf8'));
const {source,root,spaceMeals,context,pendingPrerequisiteIds}=recorded;
const authority=new PreparedFutureCollectiveParticipantClosure(source,root);
assert.deepEqual(authority.evaluate(root,[],()=>true,'NECESSARY_ONLY',spaceMeals),recorded.initial);
const result=authority.evaluate(context,[],()=>true,'NECESSARY_ONLY',spaceMeals);
// JSON records serialize an infinite necessary release bound as null.
assert.deepEqual(JSON.parse(JSON.stringify(result)),recorded.firstHall);
assert.equal(result.status,'INFEASIBLE');assert.equal(result.certified,false);
let replayed:any=null;const stop=new Error('captured first Hall');
try{searchExactPrerequisiteClosure(source,source.tasks.filter((t:any)=>pendingPrerequisiteIds.includes(t.id)).sort((a:any,b:any)=>a.id.localeCompare(b.id)),
 root,spaceMeals,source.day.end,()=>true,()=> 'DEAD_END',(tasks:any[])=>{
 const r=new PreparedFutureCollectiveParticipantClosure(source).evaluate(tasks,[],()=>true,'NECESSARY_ONLY',spaceMeals);
 if(r.status==='INFEASIBLE'){replayed=tasks;throw stop;}return 'PASS';
});}catch(error){if(error!==stop)throw error;}
assert.deepEqual(replayed,context);
for(const alternative of recorded.alternativeNecessaryPass){
 const task=source.tasks.find((t:any)=>t.id===alternative.taskId),before=context.filter((t:any)=>t.id!==task.id);
 assert.equal(canPlaceTask(source,task,alternative.start,before,spaceMeals),true);
 const r=authority.evaluate([...before,{...task,start:alternative.start,end:alternative.end}],[],()=>true,'NECESSARY_ONLY',spaceMeals);
 assert.equal(r.status,'PASS');assert.equal(r.certified,false);
}
console.log(JSON.stringify({status:'PASS',sameProducerPrefix:true,rootNecessary:'PASS',branchHall:result.hall,
 alternativeNecessaryPass:recorded.alternativeNecessaryPass,globalCertificate:false}));

