import json,pathlib,collections
root=pathlib.Path('work/asst-s2');data=json.loads((root/'baseline.cpuprofile').read_text());nodes={n['id']:n for n in data['nodes']};parents={c:n['id'] for n in data['nodes'] for c in n.get('children',[])}
events=[]
for line in (root/'baseline-profile.log').read_text().splitlines():
 try:x=json.loads(line)
 except:continue
 if x.get('event') in ['input','core_enter','core_exit']:events.append(x)
input2=next(x for x in events if x['event']=='input' and x['request']==2)
ranges={'S2':(input2['hrtimeMs']*1000,float('inf'))}
for n in [3,6]:
 a=next(x for x in events if x['event']=='core_enter' and x['request']==2 and x['core']==n)
 b=next(x for x in events if x['event']=='core_exit' and x['request']==2 and x['core']==n)
 ranges[f'core{n}']=(a['hrtimeMs']*1000,b['hrtimeMs']*1000)
self={key:collections.Counter() for key in ranges};inclusive={key:collections.Counter() for key in ranges};total=collections.Counter();timestamp=data['startTime']
for id,delta in zip(data['samples'],data['timeDeltas']):
 timestamp+=delta
 groups=[key for key,(a,b) in ranges.items() if a<=timestamp<=b]
 if not groups:continue
 own=nodes[id]['callFrame']['functionName'] or '(anonymous)';seen=set();current=id
 while current in nodes:
  frame=nodes[current]['callFrame'];name=frame['functionName'] or '(anonymous)'
  if name not in seen:
   for key in groups:inclusive[key][name]+=delta
   seen.add(name)
  current=parents.get(current)
 for key in groups:self[key][own]+=delta;total[key]+=delta
rows=lambda c,n:[{'name':k,'ms':v/1000} for k,v in c.most_common(n)]
r={key:{'totalMs':total[key]/1000,'self':rows(self[key],25),'inclusive':rows(inclusive[key],45)} for key in ranges}
r['qualification']='Read-only CPU sample; own time excludes children. Inclusive categories overlap. Profile/observer overhead affects latency; all branch decisions remain original until a read-only throw at the per-request 300 s ceiling.'
(root/'cpu-summary.json').write_text(json.dumps(r,indent=2));print(json.dumps(r,indent=2))
